WITH flagged AS (SELECT *, CASE WHEN LAG(started_at) OVER (PARTITION BY country ORDER BY started_at, id) IS NULL OR started_at > LAG(started_at) OVER (PARTITION BY country ORDER BY started_at, id) + INTERVAL '14' DAY THEN 1 ELSE 0 END AS new_group_flag FROM sessions), islands AS (SELECT id, customer_id, device, browser, started_at, country, SUM(new_group_flag) OVER (PARTITION BY country ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM flagged) SELECT s.id, s.customer_id, s.device, s.browser, s.started_at, s.country, s.burst_id, (SELECT AVG(a2.balance) FROM accounts a2 WHERE a2.customer_id = s.customer_id) AS avg_account_balance FROM islands s ORDER BY id DESC, browser DESC;
